export const getBeautyGroomingProducts = (): Product[] => BEAUTY_GROOMING_PRODUCTS;

export const getFeaturedBeautyGroomingProducts = (): Product[] => 
  BEAUTY_GROOMING_PRODUCTS.filter(product => product.featured);

export const getBeautyGroomingProductsByBadge = (badge: string): Product[] =>
  BEAUTY_GROOMING_PRODUCTS.filter(product => product.badge === badge);

export const getBeautyGroomingProductsByPriceRange = (min: number, max: number): Product[] =>
  BEAUTY_GROOMING_PRODUCTS.filter(product => product.price >= min && product.price <= max);
